 // initBudget is the total time allowed for the verification commands of one init.
-type initBudget struct{ deadline time.Time }
+type initBudget struct {
+	deadline time.Time
+	runs     []initRunTime
+	stopped  bool
+}
+
+// initRunTime is one finished verification run: its label and its wall time truncated to whole seconds.
+type initRunTime struct {
+	label   string
+	elapsed time.Duration
+}
+
+// initVerifyRun runs one verification command through initExec and prints its end line, so no
+// call site can skip it. capped says the remaining budget, not the per-command limit, applied.
+func initVerifyRun(s *sys.Session, tools verify.Tools, b *initBudget, label, command, dir string, timeout time.Duration, capped bool) (sys.Result, error) {
+	start := time.Now()
+	r, err := initExec(s, tools, command, dir, timeout)
+	if err != nil {
+		return r, err
+	}
+	elapsed := time.Since(start).Truncate(time.Second)
+	b.runs = append(b.runs, initRunTime{label: label, elapsed: elapsed})
+	if r.TimedOut {
+		s.Progress(fmt.Sprintf("kogen: %s timed out after %s", label, elapsed))
+		if capped {
+			b.stopped = true
+		}
+	} else {
+		s.Progress(fmt.Sprintf("kogen: %s finished in %s (status %d)", label, elapsed, r.Status))
+	}
+	return r, nil
+}
+
+// initBudgetLine names the three longest runs, longest first, when the budget stopped init.
+func initBudgetLine(runs []initRunTime, budget string) string {
+	longest := append([]initRunTime(nil), runs...)
+	sort.SliceStable(longest, func(i, j int) bool { return longest[i].elapsed > longest[j].elapsed })
+	if len(longest) > 3 {
+		longest = longest[:3]
+	}
+	parts := make([]string, len(longest))
+	for i, r := range longest {
+		parts[i] = fmt.Sprintf("%s %s", r.label, r.elapsed.Truncate(time.Second))
+	}
+	return "kogen: init time budget of " + budget + " used up; longest runs: " + strings.Join(parts, ", ")
+}

